<script setup lang="ts">
import { exportCsv } from '~/lib/exportCsv'
const list = ref<any[]>([]), customers = ref<any[]>([]), loading = ref(true), loadError = ref(''), saving = ref(false)
const q = ref(''), status = ref('')
const filtered = computed(() => list.value.filter(p => `${p.kode} ${p.nama} ${p.alamat} ${p.pic}`.toLowerCase().includes(q.value.toLowerCase()) && (!status.value || p.status === status.value)))
const pages = usePagination(filtered, { resetOn: [q, status] })
const detail = ref<any>(null), formOpen = ref(false), form = ref<any>({}), customerQuery = ref('')
const assetPages = usePagination(() => detail.value?.assets || [], { resetOn: detail })
const detailCustomers = computed(() => customers.value.filter(c => detail.value?.customers.includes(c.id)))
const customerPages = usePagination(detailCustomers, { resetOn: detail })
const available = computed(() => customers.value.filter(c => (!list.value.some(p => p.id !== form.value.id && p.customers.includes(c.id))) && `${c.nama} ${c.pppoe}`.toLowerCase().includes(customerQuery.value.toLowerCase())))
const assetsCount = computed(() => list.value.reduce((n, p) => n + p.assets.length, 0))
const customerCount = computed(() => list.value.reduce((n, p) => n + p.customers.length, 0))
async function load() {
  loading.value = true; loadError.value = ''
  try { const [sites, people] = await Promise.all([api('/api/pop'), api('/api/pelanggan')]); list.value = sites; customers.value = people; if (detail.value) detail.value = sites.find((p: any) => p.id === detail.value.id) || null }
  catch (e) { loadError.value = errMsg(e) } finally { loading.value = false }
}
onMounted(load)
function edit(p?: any) { form.value = p ? JSON.parse(JSON.stringify(p)) : { id: 0, kode: '', nama: '', status: 'Aktif', alamat: '', latitude: null, longitude: null, pic: '', telepon: '', upstream: '', capacity: 0, cost: 0, notes: '', assets: [], customers: [] }; customerQuery.value = ''; detail.value = null; formOpen.value = true }
function addAsset() { form.value.assets.push({ name: '', type: 'Router', serial: '', ip: '', status: 'Aktif', value: 0 }) }
async function save() {
  saving.value = true
  const body = { ...form.value, latitude: form.value.latitude === '' ? null : form.value.latitude, longitude: form.value.longitude === '' ? null : form.value.longitude }
  try { const saved = await api(form.value.id ? `/api/pop/${form.value.id}` : '/api/pop', { method: form.value.id ? 'PUT' : 'POST', body }); formOpen.value = false; toast('Data POP disimpan'); await load(); detail.value = list.value.find(p => p.id === saved.id) }
  catch (e) { toast(errMsg(e), 'error') } finally { saving.value = false }
}
function download() { exportCsv('data-pop.csv', [['Kode', 'Nama', 'Status', 'Alamat', 'Latitude', 'Longitude', 'PIC', 'Telepon', 'Upstream', 'Kapasitas Mbps', 'Estimasi biaya bulanan', 'Pelanggan', 'Perangkat'], ...filtered.value.map(p => [p.kode, p.nama, p.status, p.alamat, p.latitude ?? '', p.longitude ?? '', p.pic, p.telepon, p.upstream, p.capacity, p.cost, p.customers.length, p.assets.length])]) }
</script>
<template>
  <div class="card op-hero"><div><span class="op-eyebrow">Infrastruktur layanan</span><h2>Kenali setiap titik jaringan.</h2><p>Kelola lokasi POP, penanggung jawab, kapasitas, perangkat, dan pelanggan yang terhubung dalam satu catatan operasional.</p></div><div class="op-actions"><NuxtLink to="/surat-pop" class="btn btn-sec"><Ico name="file" :size="15" /> Surat Komdigi</NuxtLink><button class="btn btn-primary" @click="edit()"><Ico name="plus" :size="15" /> Tambah POP</button></div></div>
  <div class="op-metrics"><div class="card op-metric"><span>Total POP</span><strong>{{ list.length }}</strong><small>{{ list.filter(p => p.status === 'Aktif').length }} berstatus aktif</small></div><div class="card op-metric"><span>Perangkat tercatat</span><strong>{{ assetsCount }}</strong><small>Inventaris seluruh POP</small></div><div class="card op-metric"><span>Pelanggan terhubung</span><strong>{{ customerCount }}</strong><small>Dari {{ customers.length }} pelanggan</small></div><div class="card op-metric"><span>Belum dialokasikan</span><strong>{{ customers.length - customerCount }}</strong><small>Pelanggan tanpa POP</small></div></div>
  <div class="toolbar"><div class="search-box"><Ico name="search" :size="16" /><input v-model="q" aria-label="Cari POP" placeholder="Cari kode, nama, lokasi…" /></div><select v-model="status" class="ctrl" style="width:auto" aria-label="Filter status POP"><option value="">Semua status</option><option>Aktif</option><option>Pemeliharaan</option><option>Nonaktif</option></select><div class="spacer"></div><button class="btn btn-sec" :disabled="loading || !!loadError" @click="download">Ekspor CSV</button></div>
  <div class="card"><div v-if="loading" class="empty">Memuat data POP…</div><div v-else-if="loadError" class="empty" role="alert">{{ loadError }} <button class="btn btn-sec" @click="load">Coba lagi</button></div><template v-else><div class="table-wrap"><table class="tbl"><thead><tr><th>POP / lokasi</th><th>Status</th><th>PIC / upstream</th><th class="num">Kapasitas</th><th class="num">Pelanggan</th><th class="num">Perangkat</th><th>Aksi</th></tr></thead><tbody><tr v-for="p in pages.rows" :key="p.id"><td class="cell-main">{{ p.nama }}<div class="cell-sub">{{ p.kode }} · {{ p.alamat || 'Alamat belum diisi' }}</div></td><td><span class="op-status" :class="{ off: p.status !== 'Aktif' }">{{ p.status }}</span></td><td>{{ p.pic || '—' }}<div class="cell-sub">{{ p.upstream || 'Upstream belum diisi' }}</div></td><td class="num">{{ p.capacity }} Mbps</td><td class="num">{{ p.customers.length }}</td><td class="num">{{ p.assets.length }}</td><td><div class="op-actions"><button class="btn btn-sec btn-sm" @click="detail = p">Detail</button><button class="icon-btn" :aria-label="`Edit ${p.nama}`" @click="edit(p)"><Ico name="pencil" :size="15" /></button></div></td></tr><tr v-if="!pages.total"><td colspan="7" class="empty">{{ q || status ? 'Tidak ada POP yang cocok.' : 'Belum ada POP. Tambahkan lokasi jaringan pertama Anda.' }}</td></tr></tbody></table></div><TablePagination v-model:page="pages.page" v-model:page-size="pages.pageSize" :total="pages.total" label="POP" /></template></div>
  <p class="op-text">Status dan kapasitas diisi secara manual. Estimasi biaya serta nilai inventaris tidak otomatis dibukukan; catat transaksi sebenarnya melalui jurnal dengan alokasi POP.</p>
  <UiModal :open="formOpen" :title="form.id ? 'Edit data POP' : 'Tambah POP'" wide :busy="saving" @close="formOpen = false"><form id="pop-form" @submit.prevent="save"><div class="grid-form"><div class="field"><label for="pop-code">Kode POP *</label><input id="pop-code" v-model="form.kode" class="ctrl" required maxlength="50" placeholder="POP-GTO-01" /></div><div class="field"><label for="pop-name">Nama POP *</label><input id="pop-name" v-model="form.nama" class="ctrl" required maxlength="150" /></div><div class="field full"><label for="pop-address">Alamat lokasi</label><textarea id="pop-address" v-model="form.alamat" class="ctrl" rows="2" maxlength="1000"></textarea></div><div class="field"><label for="pop-status">Status operasional</label><select id="pop-status" v-model="form.status" class="ctrl"><option>Aktif</option><option>Pemeliharaan</option><option>Nonaktif</option></select></div><div class="field"><label for="pop-capacity">Kapasitas uplink (Mbps)</label><input id="pop-capacity" v-model.number="form.capacity" class="ctrl" type="number" min="0" step="1" max="100000000" required /></div><div class="field"><label for="pop-lat">Latitude (opsional)</label><input id="pop-lat" v-model.number="form.latitude" class="ctrl" type="number" min="-90" max="90" step="any" /></div><div class="field"><label for="pop-long">Longitude (opsional)</label><input id="pop-long" v-model.number="form.longitude" class="ctrl" type="number" min="-180" max="180" step="any" /></div><div class="field"><label for="pop-pic">Penanggung jawab</label><input id="pop-pic" v-model="form.pic" class="ctrl" maxlength="150" /></div><div class="field"><label for="pop-phone">Nomor kontak PIC</label><input id="pop-phone" v-model="form.telepon" class="ctrl" maxlength="60" /></div><div class="field"><label for="pop-upstream">Penyedia upstream</label><input id="pop-upstream" v-model="form.upstream" class="ctrl" maxlength="150" /></div><div class="field"><label for="pop-cost">Estimasi biaya bulanan (Rp)</label><input id="pop-cost" v-model.number="form.cost" class="ctrl" type="number" min="0" max="1000000000000" step="1" required /></div><div class="field full"><label for="pop-notes">Catatan operasional</label><textarea id="pop-notes" v-model="form.notes" class="ctrl" rows="2" maxlength="4000"></textarea></div></div><h3 style="margin-top:24px">Pelanggan terhubung</h3><p class="op-text">Satu pelanggan hanya terhubung ke satu POP. Untuk pindah, lepaskan dari POP lama terlebih dahulu. {{ form.customers?.length }} dipilih.</p><input v-model="customerQuery" class="ctrl" placeholder="Cari nama / PPPoE pelanggan" aria-label="Cari pelanggan untuk POP" /><div class="pop-selection"><label v-for="c in available" :key="c.id"><input v-model="form.customers" type="checkbox" :value="c.id" />{{ c.nama }} <span class="cell-sub">{{ c.pppoe }} · {{ c.status }}</span></label><p v-if="!available.length" class="op-text">Tidak ada pelanggan yang tersedia.</p></div><h3 style="margin-top:24px">Inventaris perangkat</h3><p class="op-text">Simpan identitas perangkat untuk pendataan. Jangan masukkan kata sandi perangkat.</p><div v-for="(a, i) in form.assets" :key="i" class="op-asset"><div class="grid-form"><div class="field"><label :for="`asset-name-${i}`">Nama perangkat *</label><input :id="`asset-name-${i}`" v-model="a.name" class="ctrl" required maxlength="150" /></div><div class="field"><label :for="`asset-type-${i}`">Jenis</label><select :id="`asset-type-${i}`" v-model="a.type" class="ctrl"><option>Router</option><option>Switch</option><option>OLT</option><option>UPS</option><option>Radio</option><option>Lainnya</option></select></div><div class="field"><label :for="`asset-serial-${i}`">Serial / kode aset</label><input :id="`asset-serial-${i}`" v-model="a.serial" class="ctrl" maxlength="150" /></div><div class="field"><label :for="`asset-ip-${i}`">Alamat IP (opsional)</label><input :id="`asset-ip-${i}`" v-model="a.ip" class="ctrl" maxlength="100" /></div><div class="field"><label :for="`asset-status-${i}`">Status perangkat</label><select :id="`asset-status-${i}`" v-model="a.status" class="ctrl"><option>Aktif</option><option>Cadangan</option><option>Perbaikan</option><option>Nonaktif</option></select></div><div class="field"><label :for="`asset-value-${i}`">Nilai perolehan (Rp)</label><input :id="`asset-value-${i}`" v-model.number="a.value" type="number" class="ctrl" min="0" max="1000000000000" step="1" required /></div></div><button class="btn btn-sec btn-sm" type="button" @click="form.assets.splice(i, 1)">Hapus perangkat dari daftar</button></div><button type="button" class="btn btn-sec" @click="addAsset">Tambah perangkat</button></form><template #footer><button class="btn btn-sec" :disabled="saving" @click="formOpen = false">Batal</button><button class="btn btn-primary" :disabled="saving" form="pop-form" type="submit">{{ saving ? 'Menyimpan…' : 'Simpan POP' }}</button></template></UiModal>
  <UiModal :open="!!detail" :title="detail ? `${detail.kode} · ${detail.nama}` : 'Detail POP'" wide @close="detail = null"><template v-if="detail"><div class="op-note"><strong>{{ detail.status }} · {{ detail.capacity }} Mbps</strong>{{ detail.alamat || 'Alamat belum diisi' }}<br>PIC: {{ detail.pic || '—' }} · {{ detail.telepon || '—' }}<br>Upstream: {{ detail.upstream || '—' }} · Estimasi biaya {{ fmtRp(detail.cost) }} / bulan<br><span v-if="detail.latitude !== null">Koordinat: {{ detail.latitude }}, {{ detail.longitude }}</span></div><p class="op-text">{{ detail.notes }}</p><h3>Inventaris perangkat</h3><div class="table-wrap"><table class="tbl"><thead><tr><th>Perangkat</th><th>Serial / IP</th><th>Status</th><th class="num">Nilai perolehan</th></tr></thead><tbody><tr v-for="(a, i) in assetPages.rows" :key="i"><td>{{ a.name }}<div class="cell-sub">{{ a.type }}</div></td><td>{{ a.serial || '—' }}<div class="cell-sub">{{ a.ip }}</div></td><td>{{ a.status }}</td><td class="num">{{ fmtRp(a.value) }}</td></tr><tr v-if="!assetPages.total"><td colspan="4" class="empty">Belum ada inventaris.</td></tr></tbody></table></div><TablePagination v-model:page="assetPages.page" v-model:page-size="assetPages.pageSize" :total="assetPages.total" label="perangkat POP" /><h3 style="margin-top:24px">Pelanggan terhubung</h3><div class="table-wrap"><table class="tbl"><thead><tr><th>Pelanggan</th><th>PPPoE</th><th>Paket</th><th>Status</th></tr></thead><tbody><tr v-for="c in customerPages.rows" :key="c.id"><td>{{ c.nama }}</td><td>{{ c.pppoe }}</td><td>{{ c.paket_nama }}</td><td>{{ c.status }}</td></tr><tr v-if="!customerPages.total"><td colspan="4" class="empty">Belum ada pelanggan terhubung.</td></tr></tbody></table></div><TablePagination v-model:page="customerPages.page" v-model:page-size="customerPages.pageSize" :total="customerPages.total" label="pelanggan POP" /></template><template #footer><NuxtLink v-if="detail" :to="`/surat-pop?pop=${detail.id}`" class="btn btn-sec">Buat surat POP ini</NuxtLink><button class="btn btn-primary" @click="edit(detail)">Edit data POP</button></template></UiModal>
</template>
